from pathlib import Path

path=Path('index.html')
s=path.read_text(encoding='utf-8')

def rep(old,new):
    global s
    if old not in s:
        raise SystemExit('Expected text not found: '+old[:140])
    s=s.replace(old,new,1)

rep(':root{--bg:#f7f3ec;--panel:#fffdf9;--ink:#302a25;--muted:#7b736b;--line:#ddd5ca;--accent:#75667b;--ok:#6f8a6f;--warn:#a77734;--danger:#9b4f47}',':root{--bg:#f7f3ec;--panel:#fffdf9;--ink:#302a25;--muted:#7b736b;--line:#ddd5ca;--accent:#75667b;--ok:#6f8a6f;--warn:#a77734;--danger:#9b4f47;--poem-font:Georgia,serif;--poem-size:25px;--poem-weight:400}')
