rep("function saveUI(){localStorage.setItem(UIKEY,JSON.stringify(ui));applyPanels()}", "const FONT_MAP={times:'\\\"Times New Roman\\\",Times,serif',garamond:'Garamond,\\\"Adobe Garamond Pro\\\",\\\"EB Garamond\\\",serif',georgia:'Georgia,serif',baskerville:'Baskerville,\\\"Baskerville Old Face\\\",serif',helvetica:'\\\"Helvetica Neue\\\",Helvetica,Arial,sans-serif'},SIZE_MAP={small:'19px',medium:'25px',large:'31px'};\nfunction applyTextPrefs(){if(!FONT_MAP[ui.poemFont])ui.poemFont='georgia';if(!SIZE_MAP[ui.poemSize])ui.poemSize='medium';const root=document.documentElement;root.style.setProperty('--poem-font',FONT_MAP[ui.poemFont]);root.style.setProperty('--poem-size',SIZE_MAP[ui.poemSize]);root.style.setProperty('--poem-weight',ui.poemFont==='helvetica'?'300':'400');$('sizeSelect').value=ui.poemSize;$('fontSelect').value=ui.poemFont}\nfunction saveUI(){localStorage.setItem(UIKEY,JSON.stringify(ui));applyPanels();applyTextPrefs()}")
