old="function openComparison(leftIndex,rightIndex){const p=active(),a=p.versions[leftIndex],b=p.versions[rightIndex];if(!a||!b)return;const w=open('','_blank');if(!w){alert('Chrome blocked the comparison window. Please allow pop-ups for Revision Room.');return}const leftLabel='Draft '+(leftIndex+1),rightLabel='Draft '+(rightIndex+1);w.document.write('<title>'+esc(p.title)+' — compare</title><style>body{font-family:Georgia;background:#f7f3ec;color:#302a25;margin:30px}header{margin-bottom:22px}header h1{margin:0 0 5px}header p{margin:0;color:#7b736b;font-family:Arial,sans-serif}main{display:grid;grid-template-columns:1fr 1fr;gap:20px}.pane{min-width:0}.v{background:white;border:1px solid #ddd5ca;border-radius:10px;padding:22px;white-space:pre-wrap;line-height:1.6;min-height:60vh}.stamp{color:#7b736b;font:12px Arial,sans-serif;margin:-7px 0 10px}@media(max-width:760px){main{grid-template-columns:1fr}}</style><header><h1>'+esc(p.title)+'</h1><p>'+leftLabel+' compared with '+rightLabel+'</p></header><main><section class=pane><h3>'+leftLabel+'</h3><div class=stamp>'+esc(new Date(a.savedAt).toLocaleString())+'</div><div class=v>'+a.html+'</div></section><section class=pane><h3>'+rightLabel+'</h3><div class=stamp>'+esc(new Date(b.savedAt).toLocaleString())+'</div><div class=v>'+b.html+'</div></section></main>');w.document.close()}"
